console.log(Number("abc")); // NaN
console.log(Number("3,5")); // NaN
console.log(Number("3.5")); // 3.5

console.log(
  Number.isNaN(Number("abc")));
// true
console.log("  Lea ".trim());
// "Lea"

function validiere(name, alter) {
  const fehler = [];
  if (name.trim() === "") {
    fehler.push("Name fehlt");
  }
  if (Number.isNaN(alter) ||
      alter < 10 || alter > 20) {
    fehler.push("Alter 10–20");
  }
  return fehler;
}

console.log(validiere(" ", 25));
// ["Name fehlt", "Alter 10–20"]
console.log(validiere("Lea", 16));
// []

form.addEventListener("submit",
  (event) => {
  event.preventDefault();
  const name = document
    .querySelector("#name").value;
  const alter = Number(document
    .querySelector("#alter").value);
  const meldung = document
    .querySelector("#meldung");

  const fehler =
    validiere(name, alter);
  if (fehler.length > 0) {
    meldung.textContent =
      fehler.join(", ");
    meldung.classList.add("fehler");
  } else {
    meldung.textContent =
      "Danke, " + name + "!";
    meldung.classList
      .remove("fehler");
  }
});

